const dl = Date.parse('2026-10-23T14:44:24.876Z');
const log = ['rem=' + (dl - Date.now())];
await bot.dismissBlockingUI();
try { await bot.equipItem(/bronze sword/i); } catch (e) {}
const done = new Set(['man','rat','giant rat','goblin','giant spider','chicken','cow','farmer','woman','duck','imp','spider','bear']);
const end = Date.now() + 30000;
while (Date.now() < end && Date.now() < dl - 5000) {
  const s = sdk.getState();
  const c = (s.nearbyNpcs || []).filter(n => n.reachable !== false && n.combatLevel >= 1 && n.combatLevel <= 9 && !done.has(n.name.toLowerCase())).sort((a,b)=>b.combatLevel-a.combatLevel);
  if (!c.length) { await sdk.waitForTicks(2); continue; }
  const t = c[0];
  const r = await bot.attack(t, 4000);
  if (!r.success) { log.push(t.name + ':' + r.reason); done.add(t.name.toLowerCase()); continue; }
  const idx = t.index;
  const tt = Date.now() + 20000;
  while (Date.now() < tt) {
    const st = sdk.getState();
    if (!(st.nearbyNpcs || []).find(n => n.index === idx)) { log.push('KILLED ' + t.name + ' lvl' + t.combatLevel); break; }
    await sdk.waitForTicks(1);
  }
  if (!(sdk.getState().nearbyNpcs || []).find(n => n.index === idx)) break;
  done.add(t.name.toLowerCase());
}
log.push('rem=' + (dl - Date.now()));
console.log(log.join('\n'));
return log;
